root='F:\AER_RETRA_CASE'; day=fullfile(root,'CCN_FULL_RERUN_20260821','day_20220601'); A=load(fullfile(day,'CCN_2022_06_01_grid_hdfqc.mat'),'M','C'); lon=-177.5:5:177.5; lat=-87.5:5:87.5; f=figure('Color','w','Position',[50 80 1500 430]); ss=[.15 .25 .40]; for q=1:3, subplot(1,3,q); Z=A.M(:,:,q); Z(Z<=0)=NaN; imagesc(lon,lat,log10(Z)); set(gca,'YDir','normal'); axis tight equal; xlabel('Longitude'); ylabel('Latitude'); title(sprintf('log_{10} CCN %.2f%% - 2022-06-01',ss(q))); cb=colorbar; cb.Label.String='log_{10}(CCN cm^{-3})'; end; sgtitle('Global CCN distribution - logarithmic scale'); exportgraphics(f,fullfile(day,'CCN_2022_06_01_global_log10.png'),'Resolution',180); close(f);
